/// Decompresses the embedded payload into a map of { chapterId: { ayahNumber: tafsirText } }
Map<int, Map<int, String>> decodeEmbeddedMuyassarTafsir() {
  final compressedBytes = base64Decode(compressedMuyassarBase64);
  final uncompressedBytes = gzip.decode(compressedBytes);
  final jsonString = utf8.decode(uncompressedBytes);
  final rawMap = jsonDecode(jsonString) as Map<String, dynamic>;

  final result = <int, Map<int, String>>{};
  for (final chapterEntry in rawMap.entries) {
    final chapterId = int.parse(chapterEntry.key);
    final versesRaw = chapterEntry.value as Map<String, dynamic>;
    final versesMap = <int, String>{};
    for (final verseEntry in versesRaw.entries) {
      versesMap[int.parse(verseEntry.key)] = verseEntry.value as String;
    }
    result[chapterId] = versesMap;
  }
  return result;
}
